# typed: strict
# frozen_string_literal: true

# Generated by scripts/formula.ts in tab0inc/happen for each release; edits here are overwritten.
class Happen < Formula
  desc "Message channel between you and a supervising Claude Code session"
  homepage "https://github.com/tab0inc/happen-releases"
  license :cannot_represent

  depends_on :macos

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/tab0inc/happen-releases/releases/download/v0.1.0/happen_0.1.0_darwin_arm64.tar.gz"
      sha256 "2d3b3f2ff922e519785e0e1810c99626a6776616652c04324beaa86c6b1c1c48"
    else
      url "https://github.com/tab0inc/happen-releases/releases/download/v0.1.0/happen_0.1.0_darwin_amd64.tar.gz"
      sha256 "6535f5299d7611a05ad57d873eda70598ed055ba79728de4af2698d726f7e626"
    end
  end

  def install
    bin.install "happen"
  end

  def caveats
    <<~EOS
      Prepare this Mac once, then start the server (it also starts at login):
        happen setup
        brew services start happen
      Then connect a browser:
        happen open
    EOS
  end

  service do
    run [opt_bin/"happen", "serve"]
    keep_alive true
    log_path var/"log/happen.log"
    error_log_path var/"log/happen.log"
    environment_variables PATH: std_service_path_env
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/happen version")
  end
end
